def transform(grid):
    H=len(grid); W=len(grid[0]); out=[row[:] for row in grid]
    pts=[(r,c) for r in range(H) for c in range(W) if grid[r][c]!=0]
    rs=[r for r,c in pts]; cs=[c for r,c in pts]
    r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
    # enclosed shape color common around exterior; inner patch is the color not on border
    border=[]; interior=[]
    for r,c in pts:
        if r in (r0,r1) or c in (c0,c1): border.append(grid[r][c])
        else: interior.append(grid[r][c])
    from collections import Counter
    a=Counter(border).most_common(1)[0][0]
    b=Counter(interior).most_common(1)[0][0]
    # expand bounding box one cell; fill its border with interior color, retaining original object
    for r in range(max(0,r0-1), min(H,r1+2)):
        for c in range(max(0,c0-1), min(W,c1+2)):
            if r in (r0-1,r1+1) or c in (c0-1,c1+1):
                if 0<=r<H and 0<=c<W: out[r][c]=b
    return out
